  v[P.SENS2] = 64 + Math.trunc(old[P.SENS2] * (127 - old[P.LFO1_SPEED]) * 63 / (127 * 127));
  const mono = old[P.PLAY_MODE] !== 0;
  v[P.UNISON_VOICES] = mono ? 4 : 2;
  v[P.UNISON_DETUNE] = group === 4 ? T.legacyTab[mono ? 12 : 11][clamp(old[P.UNISON_DETUNE], 0, 127)] : mono ? 70 : 48;
